parameters.functionCode:
const marche = items[0].json;
const result = $json; // {marche_id, status: 'gagne'|'perdu'|'annule', amount?, notes?}

if (result.status !== 'gagne') {
  return [{json: {...marche, ...result, fee: 0, invoice: null}]};
}

// CALCUL SUCCESS FEE
const feeRate = 0.01; // 1%
const feeAmount = Math.round(marche.parsed_amount * feeRate);
const feeMin = 500000; // 500k minimum
const feeMax = 10000000; // 10M maximum
const finalFee = Math.max(feeMin, Math.min(feeMax, feeAmount));

const invoiceNumber = `FEE-${new Date().getFullYear()}-${String(Date.now()).slice(-6)}`;
const dueDate = new Date(Date.now() + 30*24*60*60*1000);

// Créer facture
const invoice = {
  number: invoiceNumber,
  date: new Date().toISOString().split('T')[0],
  dueDate: dueDate.toISOString().split('T')[0],
  clientId: marche.client_id,
  clientName: marche.company_name,
  marcheReference: marche.reference,
  marcheTitle: marche.title,
  marcheAmount: marche.parsed_amount,
  feeRate: feeRate * 100,
  feeAmount: finalFee,
  status: 'emise',
  description: `Success Fee 1% (min 500k, max 10M) - Marché ${marche.reference}: ${marche.title}`
};

return [{json: {...marche, ...result, fee: finalFee, invoice}}];

